import * as THREE from './assets/three.module.js';
const container=document.querySelector('#scene'), motionButton=document.querySelector('#motion'), energize=document.querySelector('#energize'), status=document.querySelector('#scene-status');
const preference=matchMedia('(prefers-reduced-motion: reduce)');let moving=!preference.matches, burst=0, renderer, draw=()=>{};
function motionLabel(){motionButton.setAttribute('aria-pressed',String(moving));motionButton.innerHTML=`<span class="motion-icon">${moving?'Ⅱ':'▷'}</span> Motion ${moving?'on':'off'}`;}
motionLabel();motionButton.addEventListener('click',()=>{moving=!moving;motionLabel();draw()});preference.addEventListener('change',e=>{moving=!e.matches;motionLabel();draw()});document.querySelector('#year').textContent=new Date().getFullYear();
energize.addEventListener('click',()=>{burst=1;status.textContent='Energy pulse activated.';if(!moving){status.textContent='Motion is paused. Turn motion on to animate the energy pulse.'}draw()});
try{
renderer=new THREE.WebGLRenderer({antialias:true,alpha:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setClearColor(0x080b09,0);container.append(renderer.domElement);container.classList.add('webgl');renderer.domElement.setAttribute('aria-hidden','true');
const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(37,1,.1,100);camera.position.set(0,0,10.8);const sculpture=new THREE.Group();scene.add(sculpture);
scene.add(new THREE.AmbientLight(0xcbd3c7,1.5));const key=new THREE.DirectionalLight(0xf3f5ee,5);key.position.set(-3,5,6);scene.add(key);const rim=new THREE.PointLight(0x87bd4c,80,18);rim.position.set(3,-1,3);scene.add(rim);const fill=new THREE.DirectionalLight(0xffffff,2);fill.position.set(2,-3,-2);scene.add(fill);
const metal=new THREE.MeshStandardMaterial({color:0xcbd3c7,metalness:.76,roughness:.24});const green=new THREE.MeshStandardMaterial({color:0x87bd4c,metalness:.6,roughness:.28,emissive:0x476b2d,emissiveIntensity:.32});
function plate(points,material,depth=.22){const shape=new THREE.Shape();points.forEach(([x,y],i)=>i?shape.lineTo(x,y):shape.moveTo(x,y));shape.closePath();const geo=new THREE.ExtrudeGeometry(shape,{depth,bevelEnabled:true,bevelSegments:3,steps:1,bevelSize:.035,bevelThickness:.04});geo.translate(0,0,-depth/2);return new THREE.Mesh(geo,material)}
sculpture.add(plate([[-1.48,1.25],[1.55,1.49],[.98,.88],[-1.9,.53]],metal));sculpture.add(plate([[1.55,1.49],[.07,.66],[-1.7,-1.57],[-.92,-1.06]],metal,.32));sculpture.add(plate([[-1.7,-1.57],[1.6,-.79],[1.04,-1.39]],metal));const accent=plate([[-1.5,-1.42],[.09,-.63],[.94,.31],[.56,.31]],green,.28);accent.position.z=-.03;sculpture.add(accent);
const orbital=new THREE.Group();scene.add(orbital);const rings=[];for(let i=0;i<3;i++){const ring=new THREE.Mesh(new THREE.TorusGeometry(2.63+i*.22,.008,8,180),new THREE.MeshBasicMaterial({color:i===0?0x87bd4c:0x607164,transparent:true,opacity:i===0?.6:.28}));ring.rotation.set(1.08+i*.21,.24+i*.38,i*.8);orbital.add(ring);rings.push(ring)}
const halo=new THREE.Mesh(new THREE.RingGeometry(2.94,2.95,120),new THREE.MeshBasicMaterial({color:0x607164,transparent:true,opacity:.14,side:THREE.DoubleSide}));halo.position.z=-1;scene.add(halo);
const dots=new THREE.Group();orbital.add(dots);for(let i=0;i<7;i++){const dot=new THREE.Mesh(new THREE.SphereGeometry(i===0?.048:.021,10,10),new THREE.MeshBasicMaterial({color:i<3?0x87bd4c:0xcbd3c7}));const a=i*2.399;dot.position.set(Math.cos(a)*2.7,Math.sin(a)*2.6,Math.sin(a*2)*.7);dots.add(dot)}
const pos=[];let seed=27;function rand(){seed=(seed*16807)%2147483647;return (seed-1)/2147483646}for(let i=0;i<140;i++)pos.push((rand()-.5)*12,(rand()-.5)*12,-2-rand()*4);const dustGeo=new THREE.BufferGeometry();dustGeo.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));const dust=new THREE.Points(dustGeo,new THREE.PointsMaterial({color:0x87bd4c,size:.016,transparent:true,opacity:.45}));scene.add(dust);
let pointerX=0,pointerY=0,rotation=0,dragging=false,lastX=0,phase=0,last=performance.now();container.addEventListener('pointerdown',e=>{if(!moving)return;dragging=true;lastX=e.clientX;container.setPointerCapture(e.pointerId)});container.addEventListener('pointermove',e=>{const r=container.getBoundingClientRect();pointerX=(e.clientX-r.left)/r.width-.5;pointerY=(e.clientY-r.top)/r.height-.5;if(dragging){rotation+=(e.clientX-lastX)*.007;lastX=e.clientX}});const release=()=>dragging=false;container.addEventListener('pointerup',release);container.addEventListener('pointercancel',release);container.addEventListener('pointerleave',()=>{pointerX=pointerY=0});
function resize(){const r=container.getBoundingClientRect();renderer.setSize(r.width,r.height);camera.aspect=r.width/r.height;camera.position.z=camera.aspect<.8?12.2:10.8;camera.updateProjectionMatrix();draw()}
draw=()=>renderer.render(scene,camera);new ResizeObserver(resize).observe(container);sculpture.rotation.set(-.14,-.24,-.08);resize();
function tick(now){requestAnimationFrame(tick);const delta=Math.min((now-last)/1000,.05);last=now;if(document.hidden||!moving)return;phase+=delta;burst=Math.max(0,burst-delta*.48);sculpture.rotation.y+=((- .24+pointerX*.45+rotation+Math.sin(phase*.35)*.14)-sculpture.rotation.y)*.045;sculpture.rotation.x+=((-.12+pointerY*.3)-sculpture.rotation.x)*.04;sculpture.position.y=Math.sin(phase*.85)*.1;sculpture.rotation.z=-.08+Math.sin(phase*.4)*.035;orbital.rotation.z+=delta*(.035+burst*.55);orbital.rotation.y=Math.sin(phase*.25)*.1;dots.rotation.z-=delta*.07;dust.rotation.z=phase*.006;rim.intensity=80+burst*150;green.emissiveIntensity=.32+burst*2;const scale=1+Math.sin(burst*Math.PI)*.08;sculpture.scale.setScalar(scale);draw()};requestAnimationFrame(tick);
renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();container.classList.remove('webgl');status.textContent='Showing the Zaiveriq emblem while 3D rendering is unavailable.'});
}catch(error){container.classList.remove('webgl');energize.hidden=true;motionButton.hidden=true;document.querySelector('.drag-hint').textContent='ZAIVERIQ LABS / COMING SOON';console.warn('3D unavailable; showing brand artwork.',error)}
